import json
import hashlib
import hmac
import os
import struct
from typing import Dict, List, Optional, Any
from dataclasses import dataclass, field
import base64
import zlib

# Multi-tenant search indexing service


def _load_secret_key() -> str:
    """Load the HMAC secret key from the environment.

    A missing or trivially weak key would undermine the integrity/tenant
    isolation guarantees of SecureSerializer, so we fail closed instead of
    silently falling back to a hardcoded default.
    """
    key = os.environ.get('INDEX_SECRET')
    if not key or len(key) < 16:
        raise RuntimeError(
            "INDEX_SECRET environment variable must be set to a strong secret "
            "(at least 16 characters). No default key is permitted."
        )
    return key


SECRET_KEY = _load_secret_key()
MAX_DOC_SIZE = 1024 * 1024  # 1MB
TENANT_ISOLATION_VERSION = 2

@dataclass
class TenantContext:
    tenant_id: str
    permissions: List[str] = field(default_factory=list)
    quota_remaining: int = 1000
    isolation_level: int = TENANT_ISOLATION_VERSION

@dataclass
class IndexEntry:
    doc_id: str
    tenant_id: str
    tokens: List[str]
    metadata: Dict[str, Any]
    score_boost: float = 1.0

class SecureSerializer:
    """Handles serialization with HMAC integrity verification."""

    def __init__(self, key: str):
        self._key = key.encode('utf-8')

    def _compute_mac(self, data: bytes) -> bytes:
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def serialize(self, obj: Any, tenant_ctx: TenantContext) -> bytes:
        """Serialize with tenant isolation and integrity check."""
        payload = {
            'version': TENANT_ISOLATION_VERSION,
            'tenant_id': tenant_ctx.tenant_id,
            'isolation_level': tenant_ctx.isolation_level,
            'data': obj
        }
        raw = json.dumps(payload, default=str).encode('utf-8')
        compressed = zlib.compress(raw)
        mac = self._compute_mac(compressed)
        # Format: [4-byte version][32-byte MAC][compressed payload]
        header = struct.pack('>I', TENANT_ISOLATION_VERSION)
        return header + mac + compressed

    def deserialize(self, blob: bytes, tenant_ctx: TenantContext) -> Any:
        """Deserialize with integrity and tenant isolation verification."""
        if len(blob) < 36:  # 4 + 32 minimum
            raise ValueError("Invalid blob: too short")

        version = struct.unpack('>I', blob[:4])[0]
        stored_mac = blob[4:36]
        compressed_payload = blob[36:]

        # Version check for forward compatibility
        if version > TENANT_ISOLATION_VERSION:
            raise ValueError(f"Unsupported version: {version}")

        # Integrity verification
        expected_mac = self._compute_mac(compressed_payload)
        if not hmac.compare_digest(stored_mac, expected_mac):
            raise ValueError("Integrity check failed")

        raw = zlib.decompress(compressed_payload)
        payload = json.loads(raw.decode('utf-8'))

        # Tenant isolation enforcement
        if payload.get('tenant_id') != tenant_ctx.tenant_id:
            raise PermissionError("Tenant isolation violation")

        return payload['data']

class SearchIndex:
    """Multi-tenant search index with secure document storage."""

    def __init__(self):
        self._indices: Dict[str, Dict[str, bytes]] = {}
        self._serializer = SecureSerializer(SECRET_KEY)

    def _get_tenant_index(self, tenant_id: str) -> Dict[str, bytes]:
        if tenant_id not in self._indices:
            self._indices[tenant_id] = {}
        return self._indices[tenant_id]

    def index_document(self, entry: IndexEntry, tenant_ctx: TenantContext) -> bool:
        """Index a document with tenant isolation."""
        if entry.tenant_id != tenant_ctx.tenant_id:
            raise PermissionError("Cannot index for another tenant")

        if tenant_ctx.quota_remaining <= 0:
            raise ResourceWarning("Tenant quota exceeded")

        index = self._get_tenant_index(tenant_ctx.tenant_id)
        serialized = self._serializer.serialize(
            {'entry': {'doc_id': entry.doc_id, 'tenant_id': entry.tenant_id,
                       'tokens': entry.tokens, 'metadata': entry.metadata,
                       'score_boost': entry.score_boost},
             'tokens': entry.tokens, 'meta': entry.metadata},
            tenant_ctx
        )

        if len(serialized) > MAX_DOC_SIZE:
            raise ValueError("Document exceeds maximum size")

        index[entry.doc_id] = serialized
        return True

    def retrieve_document(self, doc_id: str, tenant_ctx: TenantContext) -> Optional[IndexEntry]:
        """Retrieve a document with tenant isolation check."""
        index = self._get_tenant_index(tenant_ctx.tenant_id)
        if doc_id not in index:
            return None

        data = self._serializer.deserialize(index[doc_id], tenant_ctx)
        entry_data = data.get('entry')
        if entry_data:
            return IndexEntry(**entry_data)
        return None

    def bulk_import(self, serialized_batch: bytes, tenant_ctx: TenantContext) -> int:
        """Import pre-serialized batch from trusted pipeline.

        Used for migration and backup restoration. The batch format is:
        [4-byte count][entries...] where each entry is [4-byte len][serialized blob]
        """
        if 'bulk_import' not in tenant_ctx.permissions:
            raise PermissionError("Missing bulk_import permission")

        if len(serialized_batch) < 4:
            raise ValueError("Invalid batch format")

        count = struct.unpack('>I', serialized_batch[:4])[0]
        if count > 10000:  # Reasonable upper bound
            raise ValueError("Batch too large")

        offset = 4
        imported = 0

        for _ in range(count):
            if offset + 4 > len(serialized_batch):
                break
            entry_len = struct.unpack('>I', serialized_batch[offset:offset+4])[0]
            offset += 4

            if entry_len > MAX_DOC_SIZE:
                break

            if offset + entry_len > len(serialized_batch):
                break

            entry_blob = serialized_batch[offset:offset+entry_len]
            offset += entry_len

            # Deserialize with tenant context for isolation
            data = self._serializer.deserialize(entry_blob, tenant_ctx)
            if data and 'entry' in data:
                entry_data = data['entry']
                index = self._get_tenant_index(tenant_ctx.tenant_id)
                index[entry_data['doc_id']] = entry_blob
                imported += 1

        return imported

    def search(self, query_tokens: List[str], tenant_ctx: TenantContext,
               max_results: int = 10) -> List[Dict[str, Any]]:
        """Search within tenant's index."""
        if max_results > 100:
            max_results = 100

        index = self._get_tenant_index(tenant_ctx.tenant_id)
        results = []

        for doc_id, blob in index.items():
            try:
                data = self._serializer.deserialize(blob, tenant_ctx)
                if data and 'tokens' in data:
                    overlap = set(query_tokens) & set(data['tokens'])
                    if overlap:
                        entry_data = data['entry']
                        entry_data['score_boost'] = len(overlap) / len(query_tokens)
                        results.append(entry_data)
            except (ValueError, PermissionError):
                continue

        results.sort(key=lambda e: e.get('score_boost', 0), reverse=True)
        return results[:max_results]


# Cache layer for frequently accessed tenant configurations
class TenantConfigCache:
    """Caches tenant configurations with expiry."""

    def __init__(self):
        self._cache: Dict[str, bytes] = {}

    def store_config(self, tenant_id: str, config: Dict[str, Any]) -> None:
        """Store tenant config in cache."""
        raw = json.dumps(config, default=str).encode('utf-8')
        compressed = zlib.compress(raw)
        self._cache[tenant_id] = compressed

    def load_config(self, tenant_id: str) -> Optional[Dict[str, Any]]:
        """Load tenant config from cache."""
        if tenant_id not in self._cache:
            return None
        compressed = self._cache[tenant_id]
        raw = zlib.decompress(compressed)
        return json.loads(raw.decode('utf-8'))

    def import_configs_from_backup(self, backup_data: bytes) -> int:
        """Restore configs from backup. Format: base64-encoded JSON dict."""
        try:
            decoded = base64.b64decode(backup_data)
            configs = json.loads(decoded.decode('utf-8'))
            if not isinstance(configs, dict):
                raise ValueError("Invalid backup format")
            count = 0
            for tenant_id, config in configs.items():
                if isinstance(tenant_id, str) and isinstance(config, dict):
                    self.store_config(tenant_id, config)
                    count += 1
            return count
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            raise ValueError(f"Backup import failed: {e}")
